// =============================================================================
// Week-3 milestone: one REAL ResNet-18 layer (layer1.0.conv1, 115.6 M MACs)
// on bare-metal RV64IMC, verified bit-for-bit against TFLite's own output.
//
// layer_data.h is GENERATED by scripts/export_layer.py and carries the whole
// test case: this layer's exact input (from the grace_hopper image), weights,
// bias, per-channel requantize parameters, and the EXPECTED output that
// TFLite itself produced. If conv2d_b0() reproduces it byte-for-byte, then
// this C code implements the same arithmetic the hardware must implement.
//
// This is the B0 (naive) version: straightforward loops, one MAC per inner
// iteration. B1 will optimize software; X1 will replace the inner loop with
// the xqmac8 instruction. The OUTER structure (window building, requantize)
// stays the same across all three, which is what makes them comparable.
// =============================================================================
#include <stdint.h>
#include "util.h"
#include "layer_data.h"

extern int printf(const char *, ...);
void thread_entry(int cid, int nc) { while (cid != 0); }

static inline uint64_t rd_instret(void) {
    uint64_t x;
    __asm__ volatile("csrr %0, minstret" : "=r"(x));
    return x;
}

// -----------------------------------------------------------------------------
// Requantize: int32 accumulator -> int8 output. THE CONFIRMED SPEC
// (EXPERIMENTS.md E2, derivation in scripts/ref_conv.py): one single rounding
// of the full 64-bit product acc*M0, shifted by (31 + rs), gemmlowp tie rule
// (ties round away from zero -> the +1 threshold bump for negative values).
// This function is, line for line, what the xrq instruction will do in
// hardware — ~10 instructions incl. two data-dependent branches, run once per
// output element. Count its cost in the profile before building the circuit.
//
// Note: >> on a negative int64 is an ARITHMETIC shift on every compiler we
// use (gcc/clang define it that way); the numpy reference does the same.
// -----------------------------------------------------------------------------
static inline int8_t requant(int32_t acc, int32_t m0, int32_t shift, int32_t zo) {
    int64_t p    = (int64_t)acc * (int64_t)m0;     // 32x32 -> 64-bit product
    int64_t mask = ((int64_t)1 << shift) - 1;
    int64_t rem  = p & mask;
    int64_t thr  = (mask >> 1) + (p < 0 ? 1 : 0);  // tie -> away from zero
    int64_t q    = (p >> shift) + (rem > thr ? 1 : 0);
    q += zo;
    if (q >  127) q =  127;                        // saturate to int8; with
    if (q < -128) q = -128;                        // zo = -128 this IS the ReLU
    return (int8_t)q;
}

static int8_t out[L_HO * L_WO * L_COUT];           // .bss, zeroed by crt.S

// One im2col "window": the kh*kw*Cin receptive field of one output position,
// gathered contiguous. Built ONCE per position and reused by all 64 output
// channels — so its cost is amortized 64x. Out-of-bounds taps are filled with
// the input ZERO POINT (= real 0.0), never integer 0: quantized padding rule.
static int8_t win[L_K];

__attribute__((noinline))
void conv2d_b0(void) {
    for (int oy = 0; oy < L_HO; oy++) {
        for (int ox = 0; ox < L_WO; ox++) {
            // ---- gather the window (NHWC input, so each tap row is Cin
            //      contiguous bytes — one small memcpy-like loop per tap)
            int p = 0;
            for (int ky = 0; ky < L_KH; ky++) {
                int iy = oy * L_STRIDE - L_PAD_T + ky;
                for (int kx = 0; kx < L_KW; kx++) {
                    int ix = ox * L_STRIDE - L_PAD_L + kx;
                    if (iy < 0 || iy >= L_H || ix < 0 || ix >= L_W) {
                        for (int c = 0; c < L_CIN; c++) win[p++] = (int8_t)L_ZA;
                    } else {
                        const int8_t *src = &L_INPUT[(iy * L_W + ix) * L_CIN];
                        for (int c = 0; c < L_CIN; c++) win[p++] = src[c];
                    }
                }
            }
            // ---- one dot product per output channel over the same window.
            // The zero point is NOT subtracted per element; it is hoisted:
            //   sum((a-za)*w) = sum(a*w) - za*sum(w)
            // where sum(w) per channel (L_WSUM) was precomputed offline.
            // So the inner loop is a PURE a*w MAC — exactly the shape that
            // xqmac8 will consume eight-at-a-time in X1.
            for (int oc = 0; oc < L_COUT; oc++) {
                const int8_t *w = &L_WEIGHTS[oc * L_K];
                int32_t acc = L_BIAS[oc] - L_ZA * L_WSUM[oc];
                for (int k = 0; k < L_K; k++)
                    acc += (int32_t)win[k] * (int32_t)w[k];
                out[(oy * L_WO + ox) * L_COUT + oc] =
                    requant(acc, L_M0[oc], L_SHIFT[oc], L_ZO);
            }
        }
    }
}

int main(int argc, char **argv) {
    const uint64_t macs = (uint64_t)L_HO * L_WO * L_COUT * L_K;

    uint64_t t0 = rd_instret();
    conv2d_b0();
    uint64_t t1 = rd_instret();
    uint64_t n = t1 - t0;

    // Bit-exact check against TFLite's own output for this layer.
    long bad = 0, first = -1;
    for (long i = 0; i < (long)sizeof(out); i++)
        if (out[i] != L_EXPECTED[i]) { if (first < 0) first = i; bad++; }

    printf("layer1.0.conv1 on RV64IMC (B0)\n");
    printf("outputs = %ld   mismatches = %ld", (long)sizeof(out), bad);
    if (bad) printf("   first at %ld: got %d want %d",
                    first, out[first], L_EXPECTED[first]);
    printf("\nMACs = %lu   instructions = %lu   instr/MAC x100 = %lu\n",
           (unsigned long)macs, (unsigned long)n,
           (unsigned long)(n * 100 / macs));
    return bad ? 1 : 0;
}
